gXH(){return"\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5\u06cc\u06d5 \u2014 \u0647\u06d5\u0631\u062f\u0648\u0648 \u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0628\u06d5\u0628\u06ce \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5 \u0626\u06ce\u0633\u062a\u0627. \u062f\u06d5\u062a\u0648\u0627\u0646\u06cc\u062a \u062f\u0648\u0627\u062a\u0631 \u06cc\u06d5\u06a9\u06ce\u06a9\u06cc \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u06d5\u06cc\u062a \u0644\u06d5 \u0695\u06cc\u0632\u06d5\u06a9\u06d5\u06cc\u06d5\u0648\u06d5."},
gXB(){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5"},
gXU(){return"\u0695\u06ce\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
Xy(a){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5 \u2014 "+a},
gXz(){return"\u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0647\u06ce\u0634\u062a\u0627 \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5\u06cc \u062a\u0627\u06cc\u0628\u06d5\u062a \u0628\u06d5\u062e\u06c6\u06cc \u0646\u06cc\u06cc\u06d5\u060c \u0628\u06c6\u06cc\u06d5 \u0646\u0627\u062a\u0648\u0627\u0646\u06ce\u062a \u0628\u0686\u06ce\u062a\u06d5 \u0698\u0648\u0648\u0631\u06d5\u0648\u06d5. \u0626\u06ce\u0633\u062a\u0627 \u06cc\u06d5\u06a9\u06ce\u06a9\u06cc \u0628\u06c6 \u062f\u0631\u0648\u0633\u062a \u0628\u06a9\u06d5 \u2014 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06cc\u06d5\u06a9\u06d5 \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5\u06af\u06d5\u06b5\u06cc \u0647\u0627\u0648\u0628\u06d5\u0634 \u0628\u06a9\u06d5."},
XA(a){return"\u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5 \u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u0627. \u0626\u06cc\u0645\u06d5\u06cc\u0644 \u0648 \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5\u06af\u06d5\u06b5 "+a+" \u0647\u0627\u0648\u0628\u06d5\u0634 \u0628\u06a9\u06d5."},
Gp(a){return"\u062f\u0631\u0648\u0633\u062a\u06a9\u0631\u062f\u0646\u06cc \u0686\u0648\u0648\u0646\u06d5\u0698\u0648\u0648\u0631\u06d5\u0648\u06d5 \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
XO(a){return"\u0695\u06ce\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u2014 "+a},
gXP(){return"\u0648\u0634\u06d5\u06cc\u06d5\u06a9\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce \u0628\u06c6 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062f\u0627\u062f\u06d5\u0646\u06ce\u062a\u060c \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce. \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06d5\u06a9\u06d5 \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u06d5\u0648 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0647\u0627\u0648\u0628\u06d5\u0634 \u0628\u06a9\u06d5 \u2014 \u0647\u06cc\u0686 \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06ce\u06a9 \u0646\u0627\u0646\u06ce\u0631\u062f\u0631\u06ce\u062a."},
